# Published-estimates comparison table (Phase 2.5 / reply to R1-4).
# Pulls this paper's headline U_{v,0} (q_v = 1) and L2 (H = 0) estimates
# dynamically from results/figures_bovc_us_g1/main_u/exhibits_data.csv and
# tabulates them beside published Buyout and VC estimates from the literature.
# Run from r_project/:  LANG=en_US.UTF-8 Rscript results/table_published_estimates.R
out.dir <- "results/figures_bovc_us_g1/step5"
dir.create(out.dir, showWarnings = FALSE, recursive = TRUE)

ex <- read.csv("results/figures_bovc_us_g1/main_u/exhibits_data.csv", stringsAsFactors = FALSE)
get.val <- function(exh, ty, w, col) {
  r <- ex[ex$exhibit == exh & ex$type == ty & ex$weighting == w & ex$H == 0 & ex$column == col, ]
  stopifnot(nrow(r) == 1L)
  r$printed[1]
}
GIT.STATE <- sprintf("%s%s", system("git rev-parse --short HEAD", intern = TRUE),
  if (length(system("git status --porcelain --untracked-files=no", intern = TRUE))) " (uncommitted changes)" else "")

bo.u.ew  <- sprintf("%s (%s)", get.val("E1", "BO", "EW", "U.beta"),  get.val("E1", "BO", "EW", "U.beta.se"))
bo.u.fw  <- sprintf("%s (%s)", get.val("E1", "BO", "FW", "U.beta"),  get.val("E1", "BO", "FW", "U.beta.se"))
vc.u.ew  <- sprintf("%s (%s)", get.val("E1", "VC", "EW", "U.beta"),  get.val("E1", "VC", "EW", "U.beta.se"))
vc.u.fw  <- sprintf("%s (%s)", get.val("E1", "VC", "FW", "U.beta"),  get.val("E1", "VC", "FW", "U.beta.se"))
bo.l2.ew <- sprintf("%s (%s)", get.val("E1", "BO", "EW", "L2.beta"), get.val("E1", "BO", "EW", "L2.beta.se"))
bo.l2.fw <- sprintf("%s (%s)", get.val("E1", "BO", "FW", "L2.beta"), get.val("E1", "BO", "FW", "L2.beta.se"))
vc.l2.ew <- sprintf("%s (%s)", get.val("E1", "VC", "EW", "L2.beta"), get.val("E1", "VC", "EW", "L2.beta.se"))
vc.l2.fw <- sprintf("%s (%s)", get.val("E1", "VC", "FW", "L2.beta"), get.val("E1", "VC", "FW", "L2.beta.se"))

bo.ab.u.ew <- sprintf("$\\hat\\beta$=%s, $\\hat\\alpha$=%s\\%%/mo",
  get.val("E2", "BO", "EW", "U.beta"), get.val("E2", "BO", "EW", "U.alpha"))
bo.ab.u.fw <- sprintf("$\\hat\\beta$=%s, $\\hat\\alpha$=%s\\%%/mo",
  get.val("E2", "BO", "FW", "U.beta"), get.val("E2", "BO", "FW", "U.alpha"))

tex <- c(
  sprintf("%% Auto-generated by r_project/results/table_published_estimates.R at commit %s", GIT.STATE), "",
  "\\begin{table}[htbp]", "\\centering", "\\scriptsize",
  "\\caption{Comparison of Buyout and Venture Capital systematic risk ($\\beta$) and abnormal performance estimates across the literature}",
  "\\label{tab:published_estimates}",
  "\\setlength{\\tabcolsep}{3pt}",
  "\\begin{tabularx}{\\linewidth}{@{}>{\\raggedright\\arraybackslash}p{2.5cm} >{\\raggedright\\arraybackslash}p{2.5cm} >{\\raggedright\\arraybackslash}p{2.6cm} >{\\raggedright\\arraybackslash}p{1.9cm} >{\\raggedright\\arraybackslash}p{1.9cm} >{\\raggedright\\arraybackslash}X@{}}", "\\toprule",
  "Study & Data (vintages) & Method & Buyout $\\beta_{MKT}$ & VC $\\beta_{MKT}$ & Abnormal performance ($\\alpha$ / PME) \\\\", "\\midrule",
  "\\multicolumn{6}{l}{\\textit{Panel A: This paper (North America USD, Preqin complete histories, $V\\le 2010$, $H=0$)}} \\\\",
  sprintf("This paper, $U_{v,0}$ (EW, main) & Preqin (1982--2010) & Pair-product $U_{v,0}$ ($q_v=1$) & %s & %s & BO %s; VC bound \\\\", bo.u.ew, vc.u.ew, bo.ab.u.ew),
  sprintf("This paper, $U_{v,0}$ (FW, main) & Preqin (1982--2010) & Pair-product $U_{v,0}$ ($q_v=1$) & %s & %s & BO %s; VC bound \\\\", bo.u.fw, vc.u.fw, bo.ab.u.fw),
  sprintf("This paper, L2 (EW, benchmark) & Preqin (1982--2010) & Pooled squared NPV ($H=0$) & %s & %s & Noise-tilted upward (T3/T4) \\\\", bo.l2.ew, vc.l2.ew),
  sprintf("This paper, L2 (FW, benchmark) & Preqin (1982--2010) & Pooled squared NPV ($H=0$) & %s & %s & Noise-tilted upward (T3/T4) \\\\", bo.l2.fw, vc.l2.fw),
  "\\midrule",
  "\\multicolumn{6}{l}{\\textit{Panel B: Selected published cash-flow and secondary-market studies}} \\\\",
  # Panel B checked on 2026-11-23 against the articles (DLP12 Table 3; FNP12 introduction;
  # KN16 Table II col. 2; ACGP18 Table III, CAPM/FF3/PS4; GVN21 introduction; Boyer et al.
  # Section III; KN24 introduction) and, for HJK14 and RS16, against their abstracts/summaries.
  "\\cite{DLP12} & TVE (1980--1993) & Pooled NPV GMM ($H=0$) & 1.31 (CAPM); 1.71 (FF3) & 2.73 (CAPM); 2.37 (FF3) & $\\alpha$ (CAPM): BO $-0.41\\%$/mo (insig.); VC $-1.09\\%$/mo \\\\",
  "\\cite{FNP12} & CEPRES buyout deals (1975--2006) & Deal-level, P\\'astor--Stambaugh 4-factor & $\\approx 1.3$ (4-f) & -- & $\\alpha \\approx 0$ with the liquidity factor \\\\",
  "\\cite{HJK14} & Burgiss (1984--2008) & Kaplan--Schoar PME ($\\beta\\equiv 1$) & 1 (imposed) & 1 (imposed) & BO beats S\\&P~500 by 20--27\\% over fund life; VC above in 1990s, below in 2000s \\\\",
  "\\cite{KN16} & Preqin VC (1979--2008) & Public-SDF GPME & -- & -- (SDF loadings) & VC GPME $-0.10$ (CAPM SDF); $+0.11$ pre-1998, $-0.14$ post-1998 \\\\",
  "\\cite{RS16} & LP cash flows, 837 funds (1984--2010) & PME with varying $\\beta$ & -- & -- & BO PME $\\approx 1.18$; inference changes little for plausible $\\beta$ \\\\",
  "\\cite{ACGP18} & Preqin (1994--2015) & Bayesian LP cash-flow panel & 1.22--1.32 & 1.72--1.80 & BO $\\alpha \\approx 4\\%$/yr (CAPM), $\\approx 0$ with more factors \\\\",
  "\\cite{GN18} & Preqin (1981--2018) & Cash-flow strip replication & -- & -- & Avg.\\ risk-adjusted profit $-6$ (BO) and $-9$ (VC) cents per \\$1 \\\\",
  "\\cite{boyer2023discount} & Secondary transactions (2006--2018) & Transaction-based buyout index & 1.76--1.79 & -- & CAPM $\\alpha \\approx 0$ \\\\",
  "\\cite{KN24} & MSCI-Burgiss (1,073 BO, 1,630 VC funds) & Benchmark-portfolio $\\alpha$ (CAPM SDF) & 0.91 & 2.37 & BO positive abnormal returns \\\\",
  "\\bottomrule", "\\end{tabularx}", "\\par\\vspace{2pt}",
  "{\\scriptsize\\textit{Notes:} Panel~A reports single-factor $\\hat\\beta_{MKT}$ (Bartlett sandwich SE in parentheses) from Table~\\ref{tab:u_l2_beta} and joint $(\\alpha,\\beta)$ estimates from Table~\\ref{tab:u_l2_alpha_beta}; VC $(\\alpha,\\beta)$ at $H=0$ sits on the $+2\\%$ monthly $\\alpha$ bound and is interior without the 1993--1997 vintages (Table~\\ref{tab:vc_without_1993_1997}). Panel~B summarizes representative findings from the private-equity cash-flow and secondary-market pricing literature; market betas are the papers' reported market loadings (model in parentheses where several are reported; ACGP18: range over CAPM, FF3 and P\\'astor--Stambaugh models), -- where a paper reports none; methodologies differ in whether $\\beta$ is estimated jointly with $\\alpha$, whether a public-calibrated SDF or PE-specific benchmark deflator is used (Appendix~\\ref{sec:appendix_sdf}), and in underlying data vendor and sample window.}",
  "\\end{table}"
)
writeLines(tex, file.path(out.dir, "table_published_estimates.tex"))
cat("wrote", file.path(out.dir, "table_published_estimates.tex"), "\n")
